import{_ as t,C as n,o,c as r,a6 as s,E as i}from"./chunks/framework.CKIbuWFA.js";const b=JSON.parse('{"title":"Find preferences and keyboard controls","description":"","frontmatter":{"title":"Find preferences and keyboard controls","docId":"user.preferences.index","translationKey":"user.preferences.index","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6790ab7171a90bda1df882c0f88626a5875da68bf4f624968b0e54815842030f","translationRevision":"6790ab7171a90bda1df882c0f88626a5875da68bf4f624968b0e54815842030f","order":10},"headers":[],"relativePath":"en/user/preferences/index.md","filePath":"en/user/preferences/index.md","lastUpdated":1794603400000}'),d={name:"en/user/preferences/index.md"};function c(l,e,u,p,h,f){const a=n("DemoFrame");return o(),r("div",null,[e[0]||(e[0]=s('<h1 id="find-preferences-and-keyboard-controls" tabindex="-1">Find preferences and keyboard controls <a class="header-anchor" href="#find-preferences-and-keyboard-controls" aria-label="Permalink to &quot;Find preferences and keyboard controls {#find-preferences-and-keyboard-controls}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Set the application language, find the correct configuration area and use supported keyboard controls comfortably. You need the desktop window open; network access is only required for the service being configured.</p><h2 id="find-the-relevant-setting" tabindex="-1">Find the relevant setting <a class="header-anchor" href="#find-the-relevant-setting" aria-label="Permalink to &quot;Find the relevant setting {#find-the-relevant-setting}&quot;">​</a></h2><ol><li>Open <strong>Settings → General</strong> to choose the interface language. Current choices are English (<code>en</code>), Spanish (<code>es</code>), Portuguese (<code>pt</code>), French (<code>fr</code>), Simplified Chinese (<code>zh</code>) and Japanese (<code>ja</code>). Language selection does not change TikTok event identifiers or plugin API names.</li><li>Review the updater controls in General: channel, automatic checks, notifications and a manual check when supported. Automatic checks are optional. Signed update availability depends on the build&#39;s published signing configuration.</li><li>Use <strong>Account</strong> for Cloud identity and its diagnostics. Use <strong>Collaboration</strong> for owner access configuration, and <strong>Teams</strong> when the host exposes that capability.</li><li>Open <strong>Plugins</strong> for plugin-wide preferences and each plugin&#39;s Settings/Connection panes. A plugin&#39;s service credentials do not belong in General settings.</li><li>Open <strong>Automations → Variables</strong> for shared runtime values, <strong>Points</strong> for earning rules and <strong>Overlays</strong> for widget design. These configuration surfaces are intentionally located beside the features they affect.</li></ol><p>Automatic installation is experimental and disabled by the current release workflow&#39;s build gates. A visible automatic-check preference does not promise automatic installation. Use the documented <a href="./../updates.html">update process</a> and make a <a href="./backups.html">backup</a> before a version change.</p><h2 id="use-supported-keyboard-controls" tabindex="-1">Use supported keyboard controls <a class="header-anchor" href="#use-supported-keyboard-controls" aria-label="Permalink to &quot;Use supported keyboard controls {#use-supported-keyboard-controls}&quot;">​</a></h2><p>Use Tab and Shift+Tab to move focus through ordinary controls and Enter/Space to activate focused buttons. In the overlay design inspector, Ctrl/Meta+Z undoes and Ctrl/Meta+Shift+Z or Ctrl/Meta+Y redoes. Text inputs retain their own undo behavior. These are editor shortcuts, not global automation hotkeys.</p><p>Escape closes the narrow navigation drawer when another control has not consumed it. Dialogs and editors may handle Escape themselves, including an unsaved-change prompt. Global hotkey automation requires a compatible installed plugin and its reported backend capabilities.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Expected result, status and recovery <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Expected result, status and recovery {#expected-result-status-and-recovery}&quot;">​</a></h2><p>These settings and local keyboard interactions are available; complete accessibility/platform acceptance is not claimed. Prefer labeled buttons, readable window sizes and paused feed scrolling when movement is distracting. If a setting appears missing, check its owning page and host capability before resetting data. See <a href="./troubleshooting.html">troubleshooting</a> for unavailable controls and <a href="./faq.html">FAQ</a> for common distinctions.</p>',11)),i(a,{scenario:"settings",locale:"en",title:"Demo: settings"})])}const m=t(d,[["render",c]]);export{b as __pageData,m as default};
